@RestController
@RequestMapping("/api/users")
public class UserController {

    private final UserRepository repo;

    public UserController(UserRepository repo) {
        this.repo = repo;
    }

    // PUT = full replacement: every field omitted from the body is overwritten
    @PutMapping("/{id}")
    public User replaceUser(@PathVariable Long id, @RequestBody User incoming) {
        incoming.setId(id);
        return repo.save(incoming);          // name/address nulled if not sent
    }

    // PATCH = partial update: only the supplied fields change
    @PatchMapping("/{id}")
    public User patchUser(@PathVariable Long id, @RequestBody Map<String, Object> updates) {
        var user = repo.findById(id).orElseThrow();
        if (updates.containsKey("email")) user.setEmail((String) updates.get("email"));
        if (updates.containsKey("name"))  user.setName((String) updates.get("name"));
        return repo.save(user);              // other fields stay intact
    }
}
