@RestController
@RequestMapping("/api/customers")
public class CustomerController {
    private final CustomerRepository customerRepository;

    public CustomerController(CustomerRepository customerRepository) {
        this.customerRepository = customerRepository;
    }

    @GetMapping  // List all: GET /api/customers?status=ACTIVE
    public ResponseEntity<List<Customer>> listCustomers(@RequestParam(required = false) String status) {
        var customers = status != null 
            ? customerRepository.findByStatus(status)
            : customerRepository.findAll();
        return ResponseEntity.ok(customers);  // 200 OK
    }

    @GetMapping("/{id}")  // Get one: GET /api/customers/123, id extracted from path
    public ResponseEntity<Customer> getCustomer(@PathVariable Long id) {
        return customerRepository.findById(id)
            .map(ResponseEntity::ok)  // 200 OK if found
            .orElse(ResponseEntity.notFound().build());  // 404 Not Found
    }

    @PostMapping  // Create: POST /api/customers with JSON body
    public ResponseEntity<Customer> createCustomer(@RequestBody Customer customer) {
        var saved = customerRepository.save(customer);
        return ResponseEntity.status(HttpStatus.CREATED)  // 201 Created
            .header("Location", "/api/customers/" + saved.id())
            .body(saved);
    }

    @PutMapping("/{id}")  // Replace: PUT /api/customers/123 with full JSON
    public ResponseEntity<Customer> replaceCustomer(@PathVariable Long id, 
                                                      @RequestBody Customer customer) {
        if (!customerRepository.existsById(id)) {
            return ResponseEntity.notFound().build();  // 404 if doesn't exist
        }
        var updated = customerRepository.save(customer.withId(id));
        return ResponseEntity.ok(updated);  // 200 OK
    }

    @PatchMapping("/{id}")  // Partial update: PATCH /api/customers/123?email=new@example.com
    public ResponseEntity<Customer> updateEmail(@PathVariable Long id, 
                                                 @RequestParam String email) {
        return customerRepository.findById(id)
            .map(c -> customerRepository.save(c.withEmail(email)))
            .map(ResponseEntity::ok)  // 200 OK
            .orElse(ResponseEntity.notFound().build());  // 404 Not Found
    }

    @DeleteMapping("/{id}")  // Delete: DELETE /api/customers/123
    public ResponseEntity<Void> deleteCustomer(@PathVariable Long id) {
        if (!customerRepository.existsById(id)) {
            return ResponseEntity.notFound().build();  // 404 if doesn't exist
        }
        customerRepository.deleteById(id);
        return ResponseEntity.noContent().build();  // 204 No Content
    }
}

@RestController
@RequestMapping("/api/orders")
public class OrderController {
    private final OrderService orderService;

    // Idempotent: calling GET 5 times doesn't change anything
    @GetMapping("/{id}")
    public ResponseEntity<Order> getOrder(@PathVariable Long id) {
        return orderService.findById(id)
            .map(ResponseEntity::ok)
            .orElse(ResponseEntity.notFound().build());
    }

    // NOT idempotent: each POST creates a new order with a new ID
    @PostMapping
    public ResponseEntity<Order> createOrder(@RequestBody Order order) {
        var saved = orderService.save(order);  // New ID assigned each time
        return ResponseEntity.status(HttpStatus.CREATED).body(saved);
    }

    // Idempotent: updating status to SHIPPED twice results in SHIPPED
    @PatchMapping("/{id}/status")
    public ResponseEntity<Order> updateStatus(@PathVariable Long id, @RequestParam String status) {
        var updated = orderService.updateStatus(id, status);
        return ResponseEntity.ok(updated);  // Same final state after multiple calls
    }

    // Idempotent: deleting twice results in resource gone, 2nd call returns 404
    @DeleteMapping("/{id}")
    public ResponseEntity<Void> deleteOrder(@PathVariable Long id) {
        orderService.delete(id);
        return ResponseEntity.noContent().build();  // Server state identical after repeat calls
    }

    // Making POST idempotent with an idempotency key
    @PostMapping("/idempotent")
    public ResponseEntity<Order> createOrderSafe(@RequestHeader("Idempotency-Key") String key,
                                                   @RequestBody Order order) {
        var saved = orderService.saveWithIdempotencyKey(key, order);  // Deduplicates retries
        return ResponseEntity.status(HttpStatus.CREATED).body(saved);
    }
}

@RestController
@RequestMapping("/api/products")
public class ProductController {
    private final ProductService productService;

    // SAFE: GET only reads data, no state changes
    @GetMapping("/{id}")
    public ResponseEntity<Product> getProduct(@PathVariable Long id) {
        return productService.findById(id)
            .map(ResponseEntity::ok)
            .orElse(ResponseEntity.notFound().build());
        // Browsers can prefetch this, CDNs can cache it
    }

    // SAFE: OPTIONS returns allowed methods, no data changes
    @RequestMapping(value = "/{id}", method = RequestMethod.OPTIONS)
    public ResponseEntity<Void> options() {
        return ResponseEntity.ok()
            .allow(HttpMethod.GET, HttpMethod.PUT, HttpMethod.DELETE)
            .build();
    }

    // UNSAFE: POST creates a new product, modifies state
    @PostMapping
    public ResponseEntity<Product> createProduct(@RequestBody Product product) {
        var saved = productService.save(product);  // State change!
        return ResponseEntity.status(HttpStatus.CREATED).body(saved);
        // Browsers won't prefetch this, requires explicit user action
    }

    // WRONG: Using GET for a delete operation breaks the safe contract
    // @GetMapping("/{id}/delete")  // Never do this!
    // public ResponseEntity<Void> deleteProduct(@PathVariable Long id) {
    //     productService.delete(id);  // Violates safe method contract
    //     return ResponseEntity.noContent().build();
    // }

    // CORRECT: DELETE is unsafe, won't be prefetched
    @DeleteMapping("/{id}")
    public ResponseEntity<Void> deleteProduct(@PathVariable Long id) {
        productService.delete(id);  // Explicitly unsafe method
        return ResponseEntity.noContent().build();
    }
}
